mapper.select:

select
etopd.*,
enccac.system_code,
enccac.ebank_serial_number,
enccac.account_date,
enccac.account_age_class

from eg_ta_other_payable_detail etopd
left join enccac on etopd.bank_org_id =enccac.bank_org_id and etopd.ebank_batch_no =enccac.ebank_batch_no
where etopd.del_flag ='0'

    and enccac.system_code = #{queryDTO.systemCode}


    and enccac.ebank_serial_number = #{queryDTO.ebankSerialNumber}


    and etopd.ebank_batch_no = #{queryDTO.ebankBatchNo}


    and to_char(etopd.reclassification_month,'YYYY-MM') = to_char(to_date(#{queryDTO.reclassificationMonth},'yyyy-MM'),'YYYY-MM')


    and enccac.account_age_class = #{queryDTO.accountAgeClass}


    and etopd.ta_other_payable_id in

        #{item}
